"""Build the day-trip landing page and keep old city-walk links useful."""
from pathlib import Path
import build_tours as site

def facts(tour):
    start=tour['start'].split(' → ')[0]
    return f'<dl class="tour-facts"><div><dt>Duration</dt><dd>{site.esc(tour["duration"])}</dd></div><div><dt>Start</dt><dd>{site.esc(start)}</dd></div><div><dt>Style</dt><dd>{site.esc(tour["style"])}</dd></div><div><dt>Price basis</dt><dd>2 adults · private tour</dd></div></dl>'

def build():
    ids=['moshi-city-tour','arusha-city-tour','marangu-village-tour','materuni-waterfall-coffee','chemka-springs-day']
    tours=[next(t for t in site.TOURS if t['id']==id) for id in ids]
    frames=[]
    for i,tour in enumerate(tours):
        frames.append(f'<figure data-slide class="{("is-active" if i==0 else "")}" aria-hidden="{str(i!=0).lower()}"{(" inert" if i else "")}>{site.img(tour["image"],site.image_alt(tour),i==0,"100vw")}<figcaption>{site.esc(tour["title"])}</figcaption></figure>')
    hero=f'''<section class="daytrip-hero" data-carousel role="region" aria-roledescription="carousel" aria-label="Tanzania day-trip destination photographs"><div class="hero-frames">{''.join(frames)}</div><div class="daytrip-hero-content"><p class="eyebrow">MOSHI · ARUSHA · MARANGU</p><h1>See more of Tanzania.<span>One day at a time.</span></h1><p>City walks, Chagga coffee, village visits and freshwater springs. Choose a local experience with a clear meeting point, practical itinerary and personal guide.</p><div class="hero-buttons"><a class="btn btn-primary" href="#city-walks">Explore the day trips ↗</a><a class="btn btn-secondary" href="index.html#contact">Plan with David</a></div></div><p class="gallery-caption" data-visible-caption>{site.esc(tours[0]['title'])}</p>{site.controls(len(frames))}</section>'''
    body=hero+'''<div class="daytrip-navigation"><p>Private experiences · estimates based on 2 adults</p><div><a href="#city-walks">City walks</a><a href="#village-coffee">Village &amp; coffee</a><a href="#nature-days">Waterfalls &amp; springs</a><a href="#compare-daytrips">Compare the essentials</a></div></div>'''
    groups=[('city-walks','GET TO KNOW THE TOWN','A local guide.<br>A different view of the city.','Three-hour walks with markets, everyday streets and a refreshment stop. Meet in your chosen city; no intercity transport is included.',['moshi-city-tour','arusha-city-tour']),('village-coffee','LIFE IN THE KILIMANJARO FOOTHILLS','Marangu, with local hosts.','A full village day with coffee preparation, a local lunch and return transport from Moshi. Waterfalls, caves and museums are optional additions.',['marangu-village-tour']),('nature-days','TAKE A DAY OUTSIDE THE TOWN','Waterfalls, coffee<br>and clear spring water.','Private day trips from Moshi. Choose the walking trails at Materuni or a relaxed visit to Chemka; activity conditions and pickup details are confirmed before departure.',['materuni-waterfall-coffee','chemka-springs-day'])]
    for id,eyebrow,title,intro,selected in groups:
        body+=f'<section class="section daytrip-group" id="{id}"><div class="section-heading split-heading"><div><p class="eyebrow">{eyebrow}</p><h2>{title}</h2></div><p>{intro}</p></div><div class="package-grid daytrip-grid">{site.selected_cards(selected)}</div></section>'
    rows=''.join(f'<tr><th scope="row"><a href="{t["id"]}.html">{site.esc(t["title"])}</a></th><td>{site.esc(t["duration"])}</td><td>{site.esc(t["start"].split(" → ")[0])}</td><td>{"Included from Moshi" if t["id"] not in ["moshi-city-tour","arusha-city-tour"] else "Meet in town"}</td><td>{site.money(t["price"])} / adult</td></tr>' for t in tours)
    body+=f'''<section class="section" id="compare-daytrips"><div class="section-heading"><p class="eyebrow">CHOOSE WITH THE DETAILS IN VIEW</p><h2>Compare your day trips.</h2><p>These estimates are for two adults travelling together. Different pickup points, children, solo travel and additional activities need their own quote.</p></div><div class="route-comparison-table" role="region" tabindex="0" aria-label="Day-trip comparison, scroll horizontally on small screens"><table><caption>Duration, departure point and transport</caption><thead><tr><th scope="col">Day trip</th><th scope="col">Duration</th><th scope="col">Starts</th><th scope="col">Transport</th><th scope="col">Estimated from</th></tr></thead><tbody>{rows}</tbody></table></div><div class="daytrip-starting-note"><p><strong>Staying in Arusha?</strong> The Arusha walk starts there. Marangu, Materuni and Chemka estimates use Moshi pickup; an Arusha transfer is quoted separately.</p><p><strong>Before confirming:</strong> share your hotel, dates, adult/child numbers, food requirements and walking or swimming needs. David confirms the route, hosts, fees and complete price in writing.</p></div></section>'''
    body+='''<section class="section destination-final-cta"><p class="section-eyebrow">PLAN YOUR LOCAL DAY</p><h2>Tell David where you’re staying.</h2><p>We’ll help you choose a suitable day trip and agree the pickup or meeting point.</p><a class="btn btn-primary" href="index.html?trip=local#contact">Request your day-trip plan ↗</a><p class="photo-note">Photographs illustrate the stated destinations. <a href="photo-credits.html">Sources, photographers and licences</a></p></section>'''
    schema={'@context':'https://schema.org','@type':'ItemList','name':'David Explora Tanzania day trips','itemListElement':[{'@type':'ListItem','position':i+1,'name':t['title'],'url':site.ORIGIN+'/'+t['id']+'.html'} for i,t in enumerate(tours)]}
    site.page('local-tanzania.html','Moshi, Arusha & Marangu Day Trips','Compare private Arusha and Moshi city walks, Marangu village and coffee tours, Materuni Waterfall and Chemka Springs day trips with clear pickup and price information.',body,tours[0]['image'],schema)
    chooser='<section class="guide-heading"><p class="eyebrow">CHOOSE YOUR CITY</p><h1>Two cities.<br>Two separate walking tours.</h1><p>Choose Moshi or Arusha for a private guided walk. The tours have different routes and meeting points; transport between the cities is not included.</p></section><section class="section"><div class="package-grid daytrip-grid">'+site.selected_cards(['moshi-city-tour','arusha-city-tour'])+'</div><p><a href="local-tanzania.html">Explore all day trips ↗</a></p></section>'
    site.page('moshi-arusha-city-walk.html','Choose a Moshi or Arusha City Walking Tour','Select the separate Moshi or Arusha walking tour, with its own guide, meeting point and estimated price.',chooser,'images/daytrips/moshi-street.webp')
    site.sitemap()
    print('Built day-trip hub and legacy city chooser')

if __name__=='__main__':build()
